actions.script:
if (ec.user.userId && !ec.user.isInGroup('ADMIN')) throw new Error('Demo loading requires system administration')
// the server's local day, as the demo data's fixed dates are read
const now = new Date(ec.user.timestampMillis(ec.user.nowTimestamp))
const dayOn = (afterDays, weekDay) => {
    const day = new Date(now.getFullYear(), now.getMonth(), now.getDate() + afterDays)
    return new Date(day.getFullYear(), day.getMonth(), day.getDate() + ((weekDay - day.getDay() + 7) % 7))
}
const at = (day, hour, plusDays = 0) => String(new Date(day.getFullYear(), day.getMonth(), day.getDate() + plusDays, hour).getTime())
const move = (entityName, keys, fields) => {
    const found = ec.entity.find(entityName).condition(keys).disableAuthz().one()
    if (found == null) {
        ec.logger.warn('The event dates demo found no ' + entityName + ' ' + JSON.stringify(keys) + '; not moved')
        return
    }
    ec.service.sync().name('update#' + entityName).parameters(Object.assign({}, keys, fields)).disableAuthz().call()
}
const webinar = dayOn(70, 4)
const workshop = dayOn(118, 6)
webinarStart = at(webinar, 18)
workshopStart = at(workshop, 9)
move('mantle.work.effort.WorkEffort', {workEffortId: 'BOSS_MKT_EV_WEBINAR'},
    {estimatedStartDate: webinarStart, estimatedCompletionDate: at(webinar, 19)})
move('mantle.work.registration.EventRegistrationPolicy', {registrationPolicyId: 'BOSS_MKT_OFFER_WEBINAR'},
    {occurrenceStart: webinarStart, occurrenceEnd: at(webinar, 19)})
move('mantle.work.effort.WorkEffort', {workEffortId: 'BOSS_MKT_EV_WORKSHOP'},
    {estimatedStartDate: workshopStart, estimatedCompletionDate: at(workshop, 12)})
move('mantle.work.registration.EventRegistrationPolicy', {registrationPolicyId: 'BOSS_MKT_OFFER_WORKSHOP'},
    {occurrenceStart: workshopStart, occurrenceEnd: at(workshop, 12), closesDate: at(workshop, 17, -1)})
